function solve(input) {
  const { nodes, edges } = input;
  const indegree = new Map();
  const adjacency = new Map();
  const nodeSet = new Set(nodes);

  for (const node of nodes) {
    indegree.set(node, 0);
    adjacency.set(node, []);
  }

  for (const edge of edges) {
    const [u, v] = edge;
    if (!nodeSet.has(u) || !nodeSet.has(v)) continue;
    if (u === v) return null;
    if (adjacency.get(u).includes(v)) continue;
    adjacency.get(u).push(v);
    indegree.set(v, indegree.get(v) + 1);
  }

  const available = [];
  for (const node of nodes) {
    if (indegree.get(node) === 0) available.push(node);
  }
  available.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);

  const order = [];
  while (available.length > 0) {
    const node = available.shift();
    order.push(node);
    for (const next of adjacency.get(node)) {
      indegree.set(next, indegree.get(next) - 1);
      if (indegree.get(next) === 0) available.push(next);
    }
    available.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
  }

  return order.length === nodes.length ? order : null;
}
