function solve(input) {
  const store = new Map();
  const results = [];

  for (const op of input) {
    if (op.op === "put") {
      store.set(op.key, { value: op.value, expires: op.t + op.ttl });
    } else if (op.op === "delete") {
      store.delete(op.key);
    } else if (op.op === "get") {
      const entry = store.get(op.key);
      if (entry === undefined || op.t >= entry.expires) {
        results.push(null);
      } else {
        results.push(entry.value);
      }
    }
  }

  return results;
}
