function solve(input) {
  const { document, pointer } = input;

  function decodeToken(token) {
    return token.replace(/~/g, (match, offset, str) =>
      str[offset + 1] === '1' ? '/' : '~'
    );
  }

  function resolve(node, tokens) {
    if (tokens.length === 0) {
      return { found: true, value: node };
    }

    const token = decodeToken(tokens[0]);

    if (node === null || typeof node !== 'object') {
      return { found: false };
    }

    if (Array.isArray(node)) {
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return { found: false };
      }
      const index = Number(token);
      if (index >= node.length) {
        return { found: false };
      }
      return resolve(node[index], tokens.slice(1));
    }

    if (!Object.prototype.hasOwnProperty.call(node, token)) {
      return { found: false };
    }

    return resolve(node[token], tokens.slice(1));
  }

  if (pointer === '') {
    return { found: true, value: document };
  }

  if (typeof pointer !== 'string' || pointer[0] !== '/') {
    return { found: false };
  }

  const tokens = pointer.slice(1).split('/');
  return resolve(document, tokens);
}
